mkuse!{use std :: { ptr , slice } ;}
mkuse!{use thin_vec :: ThinVec ;}
mkitem!{mkstruct!{# [doc = " An iterator for [`ThinVec`] which uses a closure to determine if an element should be removed."] # [must_use = "iterators are lazy and do nothing unless consumed"] pub struct ExtractIf < 'a , T , F > { vec : & 'a mut ThinVec < T > , # [doc = " The index of the item that will be inspected by the next call to `next`."] idx : usize , # [doc = " The number of items that have been drained (removed) thus far."] del : usize , # [doc = " The original length of `vec` prior to draining."] old_len : usize , # [doc = " The filter test predicate."] pred : F , }}}
mkitem!{mkimpl!{impl < 'a , T , F > ExtractIf < 'a , T , F > where F : FnMut (& mut T) -> bool , { pub fn new (vec : & 'a mut ThinVec < T > , filter : F) -> Self { let old_len = vec . len () ; unsafe { vec . set_len (0) ; } ExtractIf { vec , idx : 0 , del : 0 , old_len , pred : filter } } }}}
mkitem!{mkimpl!{impl < T , F > Iterator for ExtractIf < '_ , T , F > where F : FnMut (& mut T) -> bool , { type Item = T ; fn next (& mut self) -> Option < Self :: Item > { unsafe { while self . idx < self . old_len { let i = self . idx ; let v = slice :: from_raw_parts_mut (self . vec . as_mut_ptr () , self . old_len) ; let drained = (self . pred) (& mut v [i]) ; self . idx += 1 ; if drained { self . del += 1 ; return Some (ptr :: read (& v [i])) ; } else if self . del > 0 { let del = self . del ; let src : * const T = & v [i] ; let dst : * mut T = & mut v [i - del] ; ptr :: copy_nonoverlapping (src , dst , 1) ; } } None } } fn size_hint (& self) -> (usize , Option < usize >) { (0 , Some (self . old_len - self . idx)) } }}}
mkitem!{mkimpl!{impl < A , F > Drop for ExtractIf < '_ , A , F > { fn drop (& mut self) { unsafe { if self . idx < self . old_len && self . del > 0 { let ptr = self . vec . as_mut_ptr () ; let src = ptr . add (self . idx) ; let dst = src . sub (self . del) ; let tail_len = self . old_len - self . idx ; src . copy_to (dst , tail_len) ; } self . vec . set_len (self . old_len - self . del) ; } } }}}